  var LABELCODE = { G: 'EFG', F: 'EFG', E: 'EFG', D: 'CD', C: 'CD', B: 'AB', A: 'AB', 'A+': 'A+/A++', 'A++': 'A+/A++', 'A+++': 'A+++', 'A++++': 'A++++', 'A++++G': 'A++++ garantie', GEEN: 'geen' };
